# tap_ai/services/doctype_selector.py\n\nimport json\nimport logging\nimport hashlib\nfrom typing import List, Dict, Any, Optional\n\nimport frappe\n\nfrom tap_ai.infra.config import get_config\nfrom tap_ai.infra.llm_client import LLMClient\nfrom tap_ai.infra.sql_catalog import load_schema\n\nlogger = logging.getLogger(__name__)\n\n\n# Cache configuration\nCACHE_TTL = 300  # 5 minutes\nCACHE_PREFIX = "doctype_selector:"\n\nSYSTEM_PROMPT = """You are a routing assistant.\n\nGiven:\n- A natural language question about TAP AI data\n- A JSON schema that lists DocTypes, their fields, and link relationships\n- OPTIONAL user context (user type, grade)\n\nReturn ONLY a JSON object with:\n{\n  "doctypes": ["DocType A", "DocType B", ...],   // ordered by relevance\n  "reason": "short explanation (<= 30 words)"\n}\n\nRules:\n- Choose the minimum set of DocTypes that can answer the query.\n- Prefer DocTypes explicitly mentioning fields used in the question.\n- If user context is provided, prefer DocTypes relevant to that user type.\n- Use link relationships only if required to answer the query.\n- Keep 'doctypes' length <= TOP_N.\n- No prose outside JSON. No backticks.\n"""\n\n\ndef _schema_summary(schema: Dict[str, Any]) -> Dict[str, Any]:\n    """\n    Compact schema summary to keep prompt small.\n    """\n    tables = schema.get("tables", {})\n    links = schema.get("allowed_joins", []) or schema.get("links", [])\n\n    compact_tables = {}\n    for tname, tinfo in tables.items():\n        cols = tinfo.get("columns") or []\n        compact_tables[tname] = {\n            "doctype": tinfo.get("doctype") or tname.replace("tab", "", 1),\n            "fields": cols[:25],\n            "description": (tinfo.get("description") or "")[:160],\n        }\n\n    return {\n        "tables": compact_tables,\n        "links": links[:25],\n    }\n\ndef _get_cache_key(query: str, top_n: int, user_profile_json: Optional[str] = None) -> str:\n    """Generate cache key for doctype selection"""\n    key_data = f"{query}_{top_n}_{user_profile_json or ''}"\n    return f"{CACHE_PREFIX}{hashlib.md5(key_data.encode()).hexdigest()}"\n\ndef _get_cached_result(cache_key: str) -> Optional[List[str]]:\n    """Get cached doctype selection result"""\n    try:\n        cached = frappe.cache().get(cache_key)\n        if cached:\n            return json.loads(cached)\n    except Exception:\n        pass\n    return None\n\ndef _cache_result(cache_key: str, result: List[str]) -> None:\n    """Cache doctype selection result"""\n    try:\n        frappe.cache().set(cache_key, json.dumps(result), ex=CACHE_TTL)\n    except Exception:\n        pass\n\n\ndef pick_doctypes(\n    query: str,\n    top_n: int = 5,\n    user_profile_json: Optional[str] = None,\n) -> List[str]:\n    """\n    Pick the most relevant DocTypes for a query.\n    Uses Redis-based caching for multi-process consistency.\n    """\n    query = (query or "").strip().lower()\n\n    # Check cache first\n    cache_key = _get_cache_key(query, top_n, user_profile_json)\n    cached_result = _get_cached_result(cache_key)\n    if cached_result is not None:\n        return cached_result\n\n    # Generate result\n    schema = load_schema()\n    summary = _schema_summary(schema)\n    llm = LLMClient.get_client(\n        model=get_config("primary_llm_model") or "gpt-4o-mini",\n        temperature=0.0,\n        max_tokens=400,\n    )\n\n    # Decode user profile (optional)\n    user_profile = None\n    if user_profile_json:\n        try:\n            user_profile = json.loads(user_profile_json)\n        except Exception:\n            user_profile = None\n\n    schema_snippet = json.dumps(summary, ensure_ascii=False)\n\n    # --- Optional user context hints ---\n    user_context = ""\n    if user_profile:\n        if user_profile.get("type"):\n            user_context += f"USER TYPE: {user_profile['type']}\n"\n        if user_profile.get("grade"):\n            user_context += f"GRADE: {user_profile['grade']}\n"\n\n    user_msg = (\n        f"TOP_N={top_n}\n\n"\n        f"{user_context}\n"\n        f"QUESTION:\n{query}\n\n"\n        f"SCHEMA SUMMARY:\n{schema_snippet}"\n    )\n\n    try:\n        resp = llm.invoke(\n            [\n                ("system", SYSTEM_PROMPT),\n                ("user", user_msg),\n            ]\n        )\n        txt = resp.content.strip()\n        data = json.loads(txt)\n        doctypes = data.get("doctypes", [])\n        result = _normalize_doctypes(doctypes, summary)[:top_n]\n\n        # Cache the result\n        _cache_result(cache_key, result)\n\n        return result\n\n    except Exception as e:\n        logger.warning("DocType selection LLM failed: %s", e)\n        return []\n\ndef clear_doctype_cache():\n    """Clear all doctype selection cache"""\n    try:\n        # Get all cache keys with our prefix\n        # Note: This requires Redis SCAN command support\n        cache_keys = frappe.cache().get_keys(f"{CACHE_PREFIX}*")\n        for key in cache_keys:\n            frappe.cache().delete(key)\n    except Exception:\n        # Fallback: just let them expire naturally\n        pass\n\n\ndef _normalize_doctypes(\n    candidates: List[str],\n    summary: Dict[str, Any]\n) -> List[str]:\n    """\n    Normalize LLM-proposed names to canonical DocType names in schema.\n    """\n    schema_names = {}\n    for table_name, info in summary["tables"].items():\n        clean = info["doctype"]\n        schema_names[clean.lower()] = clean\n\n    normalized = []\n    for name in candidates:\n        key = name.lower().replace("tab", "").strip()\n        if key in schema_names:\n            normalized.append(schema_names[key])\n\n    # Deduplicate while preserving order\n    seen = set()\n    final = []\n    for d in normalized:\n        if d not in seen:\n            final.append(d)\n            seen.add(d)\n\n    return final\n\n\n
